use verus::prelude::*;
use verus::vec::Vec;

pub enum ExpandedVector<T> {
    RowVector(Vec<T>),
    ColumnVector(Vec<T>),
}

fn expand_dims<T>(a: Vec<T>, axis: usize) -> ExpandedVector<T> {
    // The spec requires axis <= 1.
    // At runtime, we branch on axis == 0 or 1.
    if axis == 0 {
        ExpandedVector::RowVector(a)
    } else {
        ExpandedVector::ColumnVector(a)
    }
}